          "const legacyState = { user: 'Priya', permissions: ['read', 'write'] };",
          "const mutatedState = legacyState;",
          "mutatedState.permissions.push('admin'); // In-place array mutation!",
          "",
          "// Shallow comparison fails to detect mutation:",
          "const detectedChangeInMutable = legacyState !== mutatedState;",
          "console.log('Mutable Detected by Shallow Equality:', detectedChangeInMutable); // FALSE!",
          "",
          "// The Production Pattern: Immutable copy-on-write derivation",
          "const initialState = { user: 'Priya', permissions: ['read', 'write'] };",
          "const nextState = {",
          "  ...initialState,",
          "  permissions: [...initialState.permissions, 'admin'] // Creates fresh array pointer",
          "};",
          "",
          "// Shallow comparison instantly detects state transition in O(1) time:",
          "const detectedChangeInImmutable = initialState !== nextState;",
          "console.log('Immutable Detected by Shallow Equality:', detectedChangeInImmutable); // TRUE!",
