          "const REACT_ELEMENT_TYPE = Symbol.for('react.element');",
          "",
          "// Factory function simulating React Element creation",
          "function createReactElement(type, props, key = null) {",
          "  const element = {",
          "    $$typeof: REACT_ELEMENT_TYPE, // Cryptographic symbol seal",
          "    type,",
          "    key,",
          "    ref: null,",
          "    props: Object.freeze({ ...props }) // Immutable props boundary",
          "  };",
