          "class FiberNode {",
          "  constructor(key, data) {",
          "    this.key = key;",
          "    this.data = data;",
          "  }",
          "}",
          "",
          "function reconcileChildList(prevList, nextList) {",
          "  const existingMap = new Map();",
          "  prevList.forEach((fiber, index) => {",
          "    const mapKey = fiber.key != null ? fiber.key : index;",
          "    existingMap.set(mapKey, fiber);",
          "  });",
          "",
          "  const operations = [];",
          "  nextList.forEach((nextItem, nextIndex) => {",
          "    const key = nextItem.key != null ? nextItem.key : nextIndex;",
          "    if (existingMap.has(key)) {",
          "      const prevFiber = existingMap.get(key);",
          "      existingMap.delete(key);",
          "      operations.push(`REUSE [key=${key}] \"${prevFiber.data}\" -> \"${nextItem.data}\"`);",
          "    } else {",
          "      operations.push(`INSERT [key=${key}] \"${nextItem.data}\"`);",
          "    }",
          "  });",
          "",
          "  existingMap.forEach((fiber, key) => {",
          "    operations.push(`DELETE [key=${key}] \"${fiber.data}\"`);",
          "  });",
          "",
          "  return operations;",
          "}",
          "",
          "const prevFibers = [",
          "  new FiberNode('job-1', 'Frontend Architect'),",
          "  new FiberNode('job-2', 'Backend Engineer'),",
          "  new FiberNode('job-3', 'DevOps Specialist')",
          "];",
          "",
