          "class ElementTree {",
          "  constructor() {",
          "    this.activeFiber = null;",
          "  }",
          "",
          "  reconcileBranch(newType, key, initialValue) {",
          "    if (this.activeFiber && this.activeFiber.type === newType && this.activeFiber.key === key) {",
          "      return `REUSE_FIBER: type=${newType} key=${key || 'none'} localState=\"${this.activeFiber.state}\"`;",
          "    }",
          "",
          "    this.activeFiber = { type: newType, key, state: initialValue };",
          "    return `MOUNT_NEW_FIBER: type=${newType} key=${key || 'none'} localState=\"${initialValue}\"`;",
          "  }",
          "}",
          "",
          "const tree = new ElementTree();",
          "",
          "console.log('--- SAME COMPONENT TYPE WITHOUT KEYS ---');",
          "console.log(tree.reconcileBranch('Counter', null, 'Admin Count: 50'));",
          "console.log(tree.reconcileBranch('Counter', null, 'User Count: 0'));",
          "",
          "console.log('--- SAME COMPONENT TYPE WITH EXPLICIT KEYS ---');",
          "console.log(tree.reconcileBranch('Counter', 'admin-scope', 'Admin Count: 50'));",
