          "class RootEventDelegator {",
          "  constructor(rootElementId) {",
          "    this.rootId = rootElementId;",
          "    this.listenerRegistry = new Map();",
          "  }",
          "",
          "  registerSyntheticListener(targetId, eventType, handler) {",
          "    const key = `${targetId}:${eventType}`;",
          "    this.listenerRegistry.set(key, handler);",
          "  }",
          "",
          "  dispatchNativeEvent(nativeEvent) {",
          "    const targetChain = nativeEvent.composedPath;",
          "    const executionLog = [];",
          "",
          "    for (const node of targetChain) {",
          "      const key = `${node}:${nativeEvent.type}`;",
          "      const handler = this.listenerRegistry.get(key);",
          "      if (handler) {",
          "        executionLog.push(handler(node));",
          "      }",
          "    }",
          "    return executionLog;",
          "  }",
          "}",
          "",
          "const root = new RootEventDelegator('root-app');",
          "root.registerSyntheticListener('submit-btn', 'click', (id) => `SUBMIT: Dispatched on ${id}`);",
