          "  constructor(enablePooling) {",
          "    this.enablePooling = enablePooling;",
          "    this.pooledInstance = { type: null, target: null, isRecycled: false };",
          "  }",
          "",
          "  allocateEvent(type, target) {",
          "    if (!this.enablePooling) {",
          "      return { type, target, isRecycled: false };",
          "    }",
          "    this.pooledInstance.type = type;",
          "    this.pooledInstance.target = target;",
          "    this.pooledInstance.isRecycled = false;",
          "    return this.pooledInstance;",
          "  }",
          "",
          "  recycleEvent(eventObj) {",
          "    if (this.enablePooling) {",
          "      eventObj.type = null;",
          "      eventObj.target = null;",
          "      eventObj.isRecycled = true;",
          "    }",
          "  }",
