          "class FiberNodeEventTree {",
          "  constructor(name, parent = null) {",
          "    this.name = name;",
          "    this.parent = parent;",
          "    this.handler = null;",
          "  }",
          "",
          "  setHandler(handler) {",
          "    this.handler = handler;",
          "  }",
          "",
          "  dispatchSyntheticBubble(event) {",
          "    let curr = this;",
          "    const logs = [];",
          "",
          "    while (curr && !event.isPropagationStopped) {",
          "      if (curr.handler) {",
          "        logs.push(curr.handler(event, curr.name));",
          "      }",
          "      curr = curr.parent;",
          "    }",
          "    return logs;",
          "  }",
          "}",
          "",
          "const parentFiber = new FiberNodeEventTree('ModalDialog');",
          "const childFiber = new FiberNodeEventTree('DeleteButton', parentFiber);",
          "",
          "parentFiber.setHandler((e, name) => `Container (${name}): Closed modal`);",
          "childFiber.setHandler((e, name) => {",
          "  e.isPropagationStopped = true;",
          "  return `Action (${name}): Deleted item [propagation stopped]`;",
          "});",
          "",
          "const propagationEvent = { isPropagationStopped: false };",
