          "  constructor() {",
          "    this.parentRenders = 0;",
          "    this.siblingRenders = 0;",
          "    this.leafRenders = 0;",
          "  }",
          "",
          "  simulateHoistedParentUpdate() {",
          "    this.parentRenders += 1;",
          "    this.siblingRenders += 1; // Unnecessary cascading re-render!",
          "    this.leafRenders += 1;",
          "  }",
          "",
          "  simulateColocatedChildUpdate() {",
          "    // Parent and sibling remain 0 re-renders",
          "    this.leafRenders += 1;",
          "  }",
          "",
          "  getMetrics() {",
          "    return {",
          "      parent: this.parentRenders,",
          "      sibling: this.siblingRenders,",
          "      leaf: this.leafRenders",
