        example: "class DependencyLoopDetector {\n  constructor() {\n    this.renderCount = 0;\n    this.effectRunCount = 0;\n  }\n\n  simulateRenderPass(isObjectDependency, filterText) {\n    this.renderCount += 1;\n    // If dependency is an object literal, fresh memory address is allocated on every pass!\n    const dep = isObjectDependency ? { query: filterText } : filterText;\n    return dep;\n  }\n}\n\nconst detector = new DependencyLoopDetector();\nconst pass1 = detector.simulateRenderPass(true, 'active');\nconst pass2 = detector.simulateRenderPass(true, 'active');\nconsole.log('Object References Identical?', Object.is(pass1, pass2));\n\nconst prim1 = detector.simulateRenderPass(false, 'active');\nconst prim2 = detector.simulateRenderPass(false, 'active');\nconsole.log('Primitive Dependencies Identical?', Object.is(prim1, prim2));",
