        example: "class SplitContextArchitecture {\n  constructor() {\n    this.state = { count: 0 };\n    // Dispatch identity is permanently stable\n    this.dispatch = (action) => {\n      if (action.type === 'INC') this.state.count += 1;\n    };\n  }\n\n  readState() {\n    return this.state.count;\n  }\n\n  getDispatch() {\n    return this.dispatch;\n  }\n}\n\nconst split = new SplitContextArchitecture();\nconst d1 = split.getDispatch();\nconst d2 = split.getDispatch();\n\nconsole.log('Dispatch Identity Stable?', d1 === d2);\nd1({ type: 'INC' });\nconsole.log('State Updated via Dispatch:', split.readState());",
