        example: "class FiberBailoutSimulator {\n  checkBailout(currentFiber, workInProgressFiber) {\n    // React Fiber beginWork check\n    const hasPendingStateUpdate = workInProgressFiber.hasStateUpdate;\n    if (hasPendingStateUpdate) return { bailedOut: false, reason: 'STATE_UPDATE' };\n\n    // Shallow comparison of props\n    const oldProps = currentFiber.memoizedProps;\n    const newProps = workInProgressFiber.pendingProps;\n    if (oldProps === newProps) return { bailedOut: true, reason: 'IDENTICAL_PROPS_POINTER' };\n\n    return { bailedOut: false, reason: 'PROPS_POINTER_CHANGED' };\n  }\n}\n\nconst sim = new FiberBailoutSimulator();\nconst sharedProps = { id: 101, label: 'Analytics' };\nconst current = { memoizedProps: sharedProps, hasStateUpdate: false };\nconst wip1 = { pendingProps: sharedProps, hasStateUpdate: false };\nconst wip2 = { pendingProps: { id: 101, label: 'Analytics' }, hasStateUpdate: false };\n\nconsole.log('Shared Reference Bailout:', sim.checkBailout(current, wip1).bailedOut);\nconsole.log('New Object Reference Bailout:', sim.checkBailout(current, wip2).bailedOut);",
