        example: "class UseMemoSimulator {\n  constructor() {\n    this.cache = null;\n    this.prevDeps = null;\n    this.executionCount = 0;\n  }\n\n  useMemo(computeFn, deps) {\n    const depsChanged = !this.prevDeps || deps.some((dep, i) => !Object.is(dep, this.prevDeps[i]));\n    if (depsChanged) {\n      this.executionCount += 1;\n      this.cache = computeFn();\n      this.prevDeps = deps;\n    }\n    return this.cache;\n  }\n}\n\nconst memo = new UseMemoSimulator();\nconst expensiveTransform = (n) => n * 1000;\n\nconst v1 = memo.useMemo(() => expensiveTransform(4), [4]);\nconst v2 = memo.useMemo(() => expensiveTransform(4), [4]); // Cached\nconsole.log('Memoized Value:', v1);\nconsole.log('Cache Hit Invocations:', memo.executionCount);\n\nconst v3 = memo.useMemo(() => expensiveTransform(8), [8]); // Dep changed\nconsole.log('Next Memoized Value:', v3);\nconsole.log('Dep Invalidation Invocations:', memo.executionCount);",
