        example: "class RoutePrefetchRegistry {\n  constructor() {\n    this.cache = new Map();\n  }\n\n  prefetch(routePath, chunkLoader) {\n    if (!this.cache.has(routePath)) {\n      this.cache.set(routePath, { status: 'PREFETCHING', data: chunkLoader() });\n    }\n    return this.cache.get(routePath);\n  }\n\n  navigate(routePath) {\n    const entry = this.cache.get(routePath);\n    if (entry && entry.status === 'PREFETCHING') {\n      return { instantRender: true, source: 'PREFETCH_CACHE', chunk: entry.data };\n    }\n    return { instantRender: false, source: 'NETWORK_FETCH' };\n  }\n}\n\nconst prefetcher = new RoutePrefetchRegistry();\nprefetcher.prefetch('/reports/executive', () => 'CHUNKS_EXECUTIVE_SUITE_V2');\n\nconst navState = prefetcher.navigate('/reports/executive');\nconsole.log('Instant Render Available:', navState.instantRender);\nconsole.log('Chunk Resolution Source:', navState.source);\nconsole.log('Loaded Chunk:', navState.chunk);",
