          "class ProductionBundleBudgetEngine {",
          "  constructor(budgets) {",
          "    this.budgets = budgets; // { maxInitialJsKb, maxAsyncChunkKb }",
          "  }",
          "",
          "  validateArtifacts(artifacts) {",
          "    const violations = [];",
          "    artifacts.forEach(file => {",
          "      const isInitial = file.name.startsWith('main') || file.name.startsWith('vendor');",
          "      const limit = isInitial ? this.budgets.maxInitialJsKb : this.budgets.maxAsyncChunkKb;",
          "      if (file.sizeKb > limit) {",
          "        violations.push({ file: file.name, sizeKb: file.sizeKb, limitKb: limit, excessKb: file.sizeKb - limit });",
          "      }",
          "    });",
          "",
          "    return { ",
          "      passed: violations.length === 0,",
          "      totalFilesScanned: artifacts.length,",
          "      violationsCount: violations.length,",
          "      status: violations.length === 0 ? 'BUDGET_MET' : 'BUDGET_EXCEEDED'",
          "    };",
          "  }",
          "}",
          "",
          "const validator = new ProductionBundleBudgetEngine({ maxInitialJsKb: 200, maxAsyncChunkKb: 150 });",
          "const buildOutputs = [",
          "  { name: 'main.abc123.js', sizeKb: 145 },",
          "  { name: 'vendor.def456.js', sizeKb: 185 },",
          "  { name: 'dashboard-chunk.ghi789.js', sizeKb: 110 }",
          "];",
          "",
          "const report = validator.validateArtifacts(buildOutputs);",
          "console.log('Bundle Budget Status:', report.status);",
          "console.log('Total Chunks Verified:', report.totalFilesScanned);",
          "console.log('Build Approved for Production:', report.passed);",
