            "class SuspenseCoordinatorSimulator {",
            "  constructor() {",
            "    this.cache = new Map();",
            "  }",
            "",
            "  readResource(key, fetcher) {",
            "    if (this.cache.has(key)) {",
            "      const record = this.cache.get(key);",
            "      if (record.status === 'RESOLVED') return record.value;",
            "      if (record.status === 'REJECTED') throw record.error;",
            "      throw record.promise;",
            "    }",
            "",
            "    const promise = fetcher().then(",
            "      val => { this.cache.set(key, { status: 'RESOLVED', value: val }); },",
            "      err => { this.cache.set(key, { status: 'REJECTED', error: err }); }",
            "    );",
            "    this.cache.set(key, { status: 'PENDING', promise });",
            "    throw promise;",
            "  }",
            "",
            "  renderWithSuspense(renderFn, fallback) {",
            "    try {",
            "      return { rendered: renderFn(), suspended: false };",
            "    } catch (thrown) {",
            "      if (thrown && typeof thrown.then === 'function') {",
            "        return { rendered: fallback, suspended: true, promise: thrown };",
            "      }",
            "      throw thrown;",
            "    }",
            "  }",
            "}",
            "",
