          "  constructor() {",
          "    this.urgentQueue = [];",
          "    this.transitionQueue = [];",
          "    this.isPending = false;",
          "  }",
          "",
          "  scheduleUrgent(action) {",
          "    this.urgentQueue.push({ type: 'INPUT_IMMEDIATE', action });",
          "    return action();",
          "  }",
          "",
          "  startTransition(action) {",
          "    this.isPending = true;",
          "    this.transitionQueue.push({ type: 'TRANSITION_DEFERRED', action });",
          "    const result = action();",
          "    this.isPending = false;",
          "    return result;",
          "  }",
          "}",
          "",
          "const scheduler = new ConcurrentSchedulerSimulator();",
          "let searchInput = '';",
          "let searchResultsCount = 0;",
