          "console.log('Urgent Input Updated:', searchInput);",
          "",
          "// Deferred heavy transition filter",
          "const res = scheduler.startTransition(() => {",
          "  searchResultsCount = 4250;",
          "  return 'FILTER_COMMITTED';",
