        example: "class ErrorBoundarySimulator {\n  constructor() {\n    this.state = { hasError: false, error: null };\n    this.telemetryLogs = [];\n  }\n\n  static getDerivedStateFromError(error) {\n    return { hasError: true, error: error.message };\n  }\n\n  componentDidCatch(error, errorInfo) {\n    this.telemetryLogs.push({ error: error.message, componentStack: errorInfo.componentStack });\n  }\n\n  render(childFn, fallbackFn) {\n    try {\n      if (this.state.hasError) return fallbackFn(this.state.error);\n      return childFn();\n    } catch (err) {\n      const nextState = ErrorBoundarySimulator.getDerivedStateFromError(err);\n      this.state = nextState;\n      this.componentDidCatch(err, { componentStack: 'at UnstableDataGrid (src/components/Grid.tsx:42)' });\n      return fallbackFn(this.state.error);\n    }\n  }\n\n  recover() {\n    this.state = { hasError: false, error: null };\n  }\n}\n\nconst boundary = new ErrorBoundarySimulator();\nconst throwingChild = () => { throw new Error('ERR_MALFORMED_JSON_FEED'); };\nconst fallback = (err) => `CrashRecoveryCard::${err}`;\n\nconst renderOutput = boundary.render(throwingChild, fallback);\nconsole.log('Boundary Caught Crash:', boundary.state.hasError);\nconsole.log('Fallback Rendered:', renderOutput);\nconsole.log('Telemetry Logged:', boundary.telemetryLogs.length === 1);\nconsole.log('Captured Stack:', boundary.telemetryLogs[0].componentStack);",
