            "function inventoryReducer(state, action) {",
            "  switch (action.type) {",
            "    case 'RESTOCK':",
            "      return { ...state, stock: state.stock + action.quantity };",
            "    case 'RESERVE':",
            "      if (state.stock < action.quantity) return state; // Invariant protection",
            "      return { ...state, stock: state.stock - action.quantity, reserved: state.reserved + action.quantity };",
            "    default:",
            "      return state;",
            "  }",
            "}",
            "",
            "function initInventory(initialCount) {",
            "  return { stock: initialCount, reserved: 0, initializedAt: '2026-11-04' };",
            "}",
            "",
            "let state = initInventory(100);",
            "console.log('Initial Stock:', state.stock);",
            "console.log('Initial Reserved:', state.reserved);",
