        example: "class ContextReducerBridge {\n  constructor(reducer, initialState) {\n    this.reducer = reducer;\n    this.state = initialState;\n    this.listeners = [];\n    this.dispatch = this.dispatch.bind(this);\n  }\n\n  dispatch(action) {\n    this.state = this.reducer(this.state, action);\n    this.listeners.forEach(fn => fn(this.state));\n  }\n\n  getState() {\n    return this.state;\n  }\n}\n\nconst cartReducer = (s, a) => {\n  if (a.type === 'ADD') return { items: [...s.items, a.item], total: s.total + a.item.price };\n  return s;\n};\n\nconst bridge = new ContextReducerBridge(cartReducer, { items: [], total: 0 });\nconst savedDispatch = bridge.dispatch;\n\nsavedDispatch({ type: 'ADD', item: { id: 'SKU_01', price: 80 } });\nsavedDispatch({ type: 'ADD', item: { id: 'SKU_02', price: 45 } });\n\nconsole.log('Dispatch Identity Preserved:', savedDispatch === bridge.dispatch);\nconsole.log('Cart Items Count:', bridge.getState().items.length);\nconsole.log('Cart Total Amount ($):', bridge.getState().total);",
