        example: "class EnterpriseCommerceEngine {\n  constructor() {\n    this.state = {\n      cart: [],\n      inventory: { 'LAPTOP_PRO': 10, 'MONITOR_4K': 5 },\n      discounts: { 'ENTERPRISE20': 0.20 },\n      appliedDiscount: 0,\n      checkoutStatus: 'IDLE' // IDLE, RESERVED, COMMITTED, ROLLED_BACK\n    };\n  }\n\n  dispatch(action) {\n    switch (action.type) {\n      case 'ADD_TO_CART': {\n        const itemStock = this.state.inventory[action.sku] || 0;\n        if (itemStock < action.qty) return { success: false, reason: 'OUT_OF_STOCK' };\n        \n        // Optimistic reservation\n        this.state.inventory[action.sku] -= action.qty;\n        this.state.cart.push({ sku: action.sku, qty: action.qty, price: action.price });\n        return { success: true };\n      }\n\n      case 'APPLY_COUPON': {\n        const discountRate = this.state.discounts[action.code] || 0;\n        this.state.appliedDiscount = discountRate;\n        return { success: discountRate > 0 };\n      }\n\n      case 'SUBMIT_CHECKOUT': {\n        this.state.checkoutStatus = 'COMMITTED';\n        const subtotal = this.state.cart.reduce((acc, i) => acc + (i.price * i.qty), 0);\n        const finalTotal = subtotal * (1 - this.state.appliedDiscount);\n        return { success: true, finalTotal: Number(finalTotal.toFixed(2)) };\n      }\n\n      case 'ROLLBACK_CHECKOUT': {\n        // Rollback all reservations\n        this.state.cart.forEach(item => {\n          this.state.inventory[item.sku] += item.qty;\n        });\n        this.state.cart = [];\n        this.state.appliedDiscount = 0;\n        this.state.checkoutStatus = 'ROLLED_BACK';\n        return { success: true };\n      }\n    }\n  }\n}\n\nconst engine = new EnterpriseCommerceEngine();\nengine.dispatch({ type: 'ADD_TO_CART', sku: 'LAPTOP_PRO', qty: 2, price: 1500 });\nengine.dispatch({ type: 'ADD_TO_CART', sku: 'MONITOR_4K', qty: 1, price: 500 });\nengine.dispatch({ type: 'APPLY_COUPON', code: 'ENTERPRISE20' });\n\nconst checkout = engine.dispatch({ type: 'SUBMIT_CHECKOUT' });\nconsole.log('Checkout Status:', engine.state.checkoutStatus);\nconsole.log('Total Items in Cart:', engine.state.cart.length);\nconsole.log('Final Discounted Total ($):', checkout.finalTotal);\nconsole.log('Remaining Laptop Inventory:', engine.state.inventory['LAPTOP_PRO']);",
